import{_ as e,o as i,c as a,ag as r}from"./chunks/framework.DNmTgtHf.js";const p=JSON.parse('{"title":"Part 17 — PKI & Certificates","description":"","frontmatter":{},"headers":[],"relativePath":"todo/study_plan/parts/Part_17_PKI.md","filePath":"todo/study_plan/parts/Part_17_PKI.md"}'),d={name:"todo/study_plan/parts/Part_17_PKI.md"};function s(n,t,o,l,c,h){return i(),a("div",null,[...t[0]||(t[0]=[r(`<h1 id="part-17-—-pki-certificates" tabindex="-1">Part 17 — PKI &amp; Certificates <a class="header-anchor" href="#part-17-—-pki-certificates" aria-label="Permalink to &quot;Part 17 — PKI &amp; Certificates&quot;">​</a></h1><blockquote><p><strong>Sprint allocation:</strong> Week 8 (shared — gets a meaningful chunk). <strong>Budget: ~4-5 hrs.</strong></p></blockquote><h2 id="_17-pki-certificates-—-topic-inventory" tabindex="-1">17 PKI &amp; Certificates — topic inventory <a class="header-anchor" href="#_17-pki-certificates-—-topic-inventory" aria-label="Permalink to &quot;17 PKI &amp; Certificates — topic inventory&quot;">​</a></h2><table tabindex="0"><thead><tr><th>#</th><th>Topic</th><th>Tags</th><th>Tier</th><th>Time</th><th>Done</th><th>Partial</th><th>Grilling</th><th>Visit Again</th><th>Notes</th><th>Resources</th></tr></thead><tbody><tr><td>1</td><td>X.509 certificate anatomy — Subject, Issuer, SANs, key usage, EKU, validity</td><td>🔴 💼 🔐 🎯</td><td>MP</td><td>1 hr 45 min</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td>💻 Warm-up: generate self-signed cert with <code>openssl req -x509...</code>, inspect with <code>openssl x509 -text -noout</code> (15 min)</td></tr><tr><td>2</td><td>Chain of trust — root → intermediate → leaf</td><td>🔴 💼 🔐 🎯</td><td>M</td><td>1 hr 5 min</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td>📺 Hussein Nasser — TLS chain of trust (YouTube, ~30 min) · 💻 Warm-up: <code>openssl s_client -connect google.com:443 -servername google.com -showcerts</code> — identify leaf/intermediate/root (20 min)</td></tr><tr><td>3</td><td>Why you never use a root directly — intermediates, ability to revoke</td><td>🔴 💼 🔐 🎯</td><td>M</td><td>30 min</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td></td></tr><tr><td>4</td><td>Certificate types — DV, OV, EV; SAN vs wildcard</td><td>🔴 💼 🔐 🎯</td><td>L</td><td>30 min</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td></td></tr><tr><td>5</td><td>CSR — what&#39;s in it, key generation flow</td><td>🔴 💼 🔐</td><td>MP</td><td>1 hr</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td></td></tr><tr><td>6</td><td>Certificate lifecycle — issuance, renewal, revocation, rotation</td><td>🔴 💼 🔐</td><td>MP</td><td>1.5 hrs</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td>📖 <a href="https://www.feistyduck.com/books/bulletproof-tls-and-pki/bulletproof-tls-and-pki-2ed-sample.pdf" target="_blank" rel="noreferrer">BPTLS 2ed free sample PDF</a> (60 pages but ~30 min effective if you skip preface + basics you already know) · 📖 smallstep &quot;Everything about certs&quot; blog (~30 min alternative)</td></tr><tr><td>7</td><td>CRL vs OCSP vs short-lived certs</td><td>🟠 💼 🔐</td><td>MP</td><td>1.5 hrs</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td></td></tr><tr><td>8</td><td>Certificate Transparency logs (CT)</td><td>🟠 💼 🔐</td><td>M</td><td>45 min</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td></td></tr><tr><td>9</td><td>Cross-signing, name constraints</td><td>🟠 💼 🔐</td><td>M</td><td>45 min</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td></td></tr><tr><td>10</td><td>Public vs private PKI — when each fits</td><td>🟠 💼 🔐</td><td>M</td><td>45 min</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td></td></tr><tr><td>11</td><td>Internal CA setup — Vault PKI, smallstep, ACM Private CA, EJBCA</td><td>🟠 💼 🔐</td><td>D</td><td>3 hrs</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td>🎓 smallstep tutorials · 📺 HashiCorp Vault PKI (30 min)</td></tr><tr><td>12</td><td>ACME protocol — Let&#39;s Encrypt automation</td><td>🟠 💼 🔐</td><td>MP</td><td>1.5 hrs</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td></td></tr><tr><td>13</td><td>Certificate pinning — public-key pinning, problems</td><td>🟠 💼 🔐</td><td>MP</td><td>1 hr</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td></td></tr><tr><td>14</td><td>keytool, openssl — daily-use commands</td><td>🟠 💼 🔐</td><td>MP</td><td>2 hrs 20 min</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td>🎓 OpenSSL Cookbook (Ristić, free online) · 💻 Warm-up: PEM → PKCS#12 → JKS conversion + reverse (20 min)</td></tr><tr><td>15</td><td>Java truststores, keystores — JKS, PKCS12</td><td>🟠 💼 🔐</td><td>MP</td><td>1.5 hrs</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td></td></tr><tr><td>16</td><td>Cert-manager (Kubernetes)</td><td>🟡 🔐</td><td>MP</td><td>1.5 hrs</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td>🎓 cert-manager.io docs</td></tr><tr><td>17</td><td>HSM-backed keys — when required (regulatory)</td><td>🟡 🔐</td><td>MP</td><td>1.5 hrs</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td></td></tr></tbody></table><h2 id="time-summary" tabindex="-1">Time summary <a class="header-anchor" href="#time-summary" aria-label="Permalink to &quot;Time summary&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Scope</th><th>Hours (zero baseline)</th><th>Weeks @ 10–12 hrs/wk</th><th>Actual time</th></tr></thead><tbody><tr><td>🔴 MUST only (Sprint priority — 3-month plan)</td><td>~6.33 hrs</td><td>~0.6 wk</td><td></td></tr><tr><td>🔴 + 🟠 HIGH (must + high — senior coverage)</td><td>~19.42 hrs</td><td>~1.8 wk</td><td></td></tr><tr><td>Full Part (all items including 🟡 MED)</td><td>~22.42 hrs</td><td>~2 wk</td><td></td></tr></tbody></table><blockquote><p>Time estimates assume zero baseline (you&#39;ve never seen the topic). Subtract whatever you already know. Fill in &quot;Actual time&quot; after finishing the Part — useful for calibrating future Parts.</p></blockquote><h2 id="key-diagrams" tabindex="-1">Key diagrams <a class="header-anchor" href="#key-diagrams" aria-label="Permalink to &quot;Key diagrams&quot;">​</a></h2><p><strong>Chain of trust:</strong></p><div class="language-mermaid vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">mermaid</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">flowchart TD</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    A[&quot;Root CA&lt;br/&gt;(self-signed, in OS/browser trust store, key offline)&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    B[&quot;Intermediate CA&lt;br/&gt;(online; signs leaf certs; revocable)&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    C[&quot;Leaf certificate&lt;br/&gt;(e.g., kyc-bank.com)&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    D[&quot;Client / server presents:&lt;br/&gt;leaf + intermediate chain&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    E[&quot;Verifier walks: leaf → intermediate → root.&lt;br/&gt;If root is trusted ✓ and each signature valid ✓&lt;br/&gt;and validity OK ✓ and not revoked ✓ → trust established&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    A --&gt;|signs| B</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    B --&gt;|signs| C</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    C --&gt; D</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    D --&gt; E</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    E -.-&gt;|trace back to| A</span></span></code></pre></div><blockquote><p>The root is what&#39;s pre-trusted (lives in OS / browser cert store). The leaf is what you actually deploy. The intermediate exists so a compromise can be revoked without invalidating every leaf under the root.</p></blockquote><h2 id="frequently-asked" tabindex="-1">Frequently asked <a class="header-anchor" href="#frequently-asked" aria-label="Permalink to &quot;Frequently asked&quot;">​</a></h2><ol><li><strong>Q:</strong> Walk through how TLS server authentication works end-to-end, starting from the browser receiving the server&#39;s certificate. <ul><li><strong>Why asked:</strong> Tests chain-of-trust understanding + how trust stores work + certificate validation steps (signature, validity, hostname/SAN match, revocation).</li></ul></li><li><strong>Q:</strong> If a CA gets compromised, what happens? How do clients learn the CA is no longer trusted? <ul><li><strong>Why asked:</strong> Tests revocation knowledge — CRL distribution, OCSP, why short-lived certs are increasingly the answer, CA pinning at OS/browser level.</li></ul></li><li><strong>Q:</strong> When would you choose private PKI over public CAs like Let&#39;s Encrypt? <ul><li><strong>Why asked:</strong> Architecture decision — internal service-to-service mTLS, regulated environments, name constraints, no public exposure of service topology.</li></ul></li><li><strong>Q:</strong> What&#39;s the difference between a CSR and a certificate? What&#39;s actually inside each? <ul><li><strong>Why asked:</strong> Tests basic understanding of the issuance flow + which side holds which key.</li></ul></li><li><strong>Q:</strong> How does ACME automate certificate issuance? What&#39;s the challenge mechanism? <ul><li><strong>Why asked:</strong> Modern operational knowledge — HTTP-01 vs DNS-01, validation flow. Let&#39;s Encrypt has changed the industry; senior should know this cold.</li></ul></li><li><strong>Q:</strong> You have a certificate in PKCS#12 format and need it in PEM for nginx. How? <ul><li><strong>Why asked:</strong> Daily ops fluency with <code>openssl pkcs12 -in cert.p12 -out cert.pem -nodes</code>.</li></ul></li><li><strong>Q:</strong> Your KYC platform talks to a regulated bank via mTLS. The bank&#39;s cert rotates next week. Walk through your rotation strategy. <ul><li><strong>Why asked:</strong> KYC-specific senior signal — connects PKI knowledge to real production work; tests dual-cert overlap windows, monitoring, customer comms.</li></ul></li></ol><h2 id="trick-questions-gotchas" tabindex="-1">Trick questions / gotchas <a class="header-anchor" href="#trick-questions-gotchas" aria-label="Permalink to &quot;Trick questions / gotchas&quot;">​</a></h2><ol><li><strong>Q:</strong> A certificate has expired but production traffic still works fine. What&#39;s going on? <ul><li><strong>Gotcha:</strong> TLS client validates expiry — <em>unless</em> your code disables certificate validation (<code>InsecureSkipVerify</code>, <code>TrustAllStrategy</code>, custom <code>HostnameVerifier</code> returning true). Common in misconfigured internal services where the dev &quot;fixed&quot; a TLS error by skipping validation.</li></ul></li><li><strong>Q:</strong> You added a SAN to a cert but clients still reject the connection. Why? <ul><li><strong>Gotcha:</strong> Three common reasons: (1) intermediate chain wasn&#39;t re-bundled with the new leaf; (2) clients cached the old cert and need a reload; (3) the new cert wasn&#39;t deployed to all backend instances behind the load balancer, so requests hit a stale cert.</li></ul></li><li><strong>Q:</strong> What&#39;s wrong with <code>openssl s_client -connect host:443</code>? <ul><li><strong>Gotcha:</strong> Missing <code>-servername host</code> (SNI). Without SNI, the server returns its <em>default</em> certificate, not the cert for the intended hostname. You may be inspecting the wrong cert and not realize.</li></ul></li><li><strong>Q:</strong> Why is certificate pinning often called a footgun? <ul><li><strong>Gotcha:</strong> Pinning ties the client to a specific public key. When that key needs to rotate (compromise, expiry, CA migration), pinned clients break until they ship an update. Mobile SDKs have bricked deployed apps doing this. Pin to a CA or use TACK/HPKP-style multi-pin with backup keys, or don&#39;t pin at all and rely on the trust store.</li></ul></li></ol><h2 id="mastery-candidates-top-3–5-from-this-part-—-suggestions-not-commitments" tabindex="-1">Mastery candidates (top 3–5 from this Part — suggestions, not commitments) <a class="header-anchor" href="#mastery-candidates-top-3–5-from-this-part-—-suggestions-not-commitments" aria-label="Permalink to &quot;Mastery candidates (top 3–5 from this Part — suggestions, not commitments)&quot;">​</a></h2><ul><li><strong>End-to-end TLS handshake walk-through with cert validation steps</strong> (~3 hrs) — connects Part 16 + 17, interview-canonical, also a Mastery candidate listed in Part 16.</li><li><strong>mTLS rotation flow for a regulated KYC bank integration</strong> (~3 hrs) — KYC-specific, immediately becomes a STAR-story narrative.</li><li><strong>OpenSSL + keytool command fluency for cert formats + inspection</strong> (~2 hrs) — daily-ops senior signal; muscle memory matters in interviews.</li><li><strong>Private CA setup with HashiCorp Vault</strong> (~3 hrs) — stretch goal; only if you also touch K8s service mesh.</li></ul><h2 id="hands-on-exercises-practice-advanced" tabindex="-1">Hands-on exercises (Practice + Advanced) <a class="header-anchor" href="#hands-on-exercises-practice-advanced" aria-label="Permalink to &quot;Hands-on exercises (Practice + Advanced)&quot;">​</a></h2><p>Warm-up OpenSSL exercises are listed inline in the topic-table Resources column (counted in main Time summary). The longer exercises below are tracked separately.</p><h3 id="practice-—-csr-private-ca-workflows-30-60-min-each" tabindex="-1">Practice — CSR + private CA workflows (~30-60 min each) <a class="header-anchor" href="#practice-—-csr-private-ca-workflows-30-60-min-each" aria-label="Permalink to &quot;Practice — CSR + private CA workflows (~30-60 min each)&quot;">​</a></h3><ol><li><strong>CSR generation + manual signing</strong> (~45 min) — generate a CSR with <code>openssl req -new -key client.key -out client.csr</code>. Sign it with your self-signed CA. Verify the resulting cert chain validates: <code>openssl verify -CAfile cert.pem client-signed.pem</code>.</li><li><strong>Spring Boot mTLS server + Java client</strong> (~60 min) — Spring Boot <code>server.ssl.client-auth=need</code> with your truststore. Java client using <code>SSLContext</code> with the issued client cert. Hit endpoint, verify auth via cert subject.</li></ol><h3 id="advanced-—-private-ca-rotation-60-min-each" tabindex="-1">Advanced — private CA + rotation (~60+ min each) <a class="header-anchor" href="#advanced-—-private-ca-rotation-60-min-each" aria-label="Permalink to &quot;Advanced — private CA + rotation (~60+ min each)&quot;">​</a></h3><ol start="3"><li><strong>smallstep private CA setup</strong> (~90 min) — <code>step ca init</code> for a 2-tier CA. Issue a leaf cert. Wire it into a local nginx serving HTTPS. Document the rotation flow you&#39;d use to renew the leaf in production.</li><li><strong>Cert rotation with zero downtime</strong> (~60 min) — Spring Boot service trusting two CA certs in its truststore. Rotate the upstream cert from CA-1-issued to CA-2-issued without restarting. Validates the &quot;dual cert window&quot; rotation pattern relevant to your KYC bank integrations.</li></ol><h3 id="hands-on-time-summary-practice-advanced-only" tabindex="-1">Hands-on time summary (Practice + Advanced only) <a class="header-anchor" href="#hands-on-time-summary-practice-advanced-only" aria-label="Permalink to &quot;Hands-on time summary (Practice + Advanced only)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Tier</th><th>Total time</th><th>Weeks @ 10–12 hrs/wk</th><th>Actual time</th></tr></thead><tbody><tr><td>Practice (CSR + mTLS workflows)</td><td>~1.75 hrs</td><td>~0.16 wk</td><td></td></tr><tr><td>Advanced (private CA + rotation)</td><td>~2.5 hrs</td><td>~0.23 wk</td><td></td></tr><tr><td><strong>Combined hands-on (Practice + Advanced)</strong></td><td><strong>~4.25 hrs</strong></td><td><strong>~0.4 wk</strong></td><td></td></tr></tbody></table><blockquote><p>Warm-up exercises (counted in main Time summary above) total ~55 min for Part 17 across 3 in-table warm-ups.</p></blockquote><h2 id="quick-recall" tabindex="-1">Quick recall <a class="header-anchor" href="#quick-recall" aria-label="Permalink to &quot;Quick recall&quot;">​</a></h2><p><strong>Q. Why use intermediate certificates instead of issuing leaf certs directly from the root?</strong> A. Root key stays offline. If an intermediate gets compromised, you revoke and replace it without invalidating every leaf cert under that root.</p><p><strong>Q. What&#39;s the difference between a certificate and a CSR?</strong> A. CSR (Certificate Signing Request) is what you send to a CA — contains your public key + identity info + signature made with your private key. The cert is what the CA returns after signing — same content plus the CA&#39;s signature.</p><p><strong>Q. CRL vs OCSP — when does each fit?</strong> A. CRL = full revocation list downloaded periodically (heavy, stale). OCSP = real-time per-cert check (fresh but adds a network call). OCSP stapling has the server pre-fetch the OCSP response and attach it to the TLS handshake (best of both).</p><p><strong>Q. What does the chain of trust verify?</strong> A. Each certificate is signed by the next one up. Walks from leaf to a trusted root in the local trust store. If any link is missing, invalid, expired, or revoked, the chain breaks and the connection fails.</p><p><strong>Q. What does a typical certificate rotation flow look like in production?</strong> A. Generate new key + CSR → CA issues new cert → deploy new cert alongside old (dual-cert window) → clients reconnect picking up new cert → monitor for any rejections → remove old cert after confidence window.</p><p><strong>Q. Why is hardcoded cert pinning a fragile pattern?</strong> A. Pinning ties the client to the current public key. If you rotate (compromise / expiry / CA migration), every pinned client breaks until they update. SDKs that pinned aggressively have bricked themselves during emergency rotations.</p>`,33)])])}const g=e(d,[["render",s]]);export{p as __pageData,g as default};
